// 帳票出力をテンプレートメソッドで作る
// ここを変えてみよう:StockReport の在庫数を 20 にする / 新しい帳票クラスを足してみる
abstract class Report {
    // 処理の流れは親が固定する(final で上書き禁止)
    final String print() {
        return "【" + title() + "】\n"
             + body() + "\n"
             + "-- 以上 --";
    }
    abstract String title();   // 差分は子が埋める
    abstract String body();
}

class SalesReport extends Report {
    private final int total;
    SalesReport(int total) { this.total = total; }
    @Override String title() { return "売上日報"; }
    @Override String body() { return "売上合計: " + total + "円"; }
}

class StockReport extends Report {
    private final String item;
    private final int count;
    StockReport(String item, int count) {
        this.item = item;
        this.count = count;
    }
    @Override String title() { return "在庫報告"; }
    @Override String body() {
        String mark = (count < 10) ? "(要発注)" : "";
        return item + ": " + count + "個" + mark;
    }
}

// 親の型(Report)でまとめて扱える。print() の流れは全部共通
Report[] reports = {
    new SalesReport(12000),
    new StockReport("コピー用紙", 8)
};
for (Report r : reports) {
    System.out.println(r.print());
}
