// 料金計算ルールをインターフェースで差し替える
// ここを変えてみよう:SaleDiscount の割引率を変える / NoDiscount の label() を消してみる
interface PriceRule {
    int apply(int price);                 // 暗黙に public abstract

    default String label() {              // default メソッド(Java 8+)
        return "ルール";
    }
    static String yen(int price) {        // static メソッド
        return String.format("%,d円", price);
    }
}

class NoDiscount implements PriceRule {
    public int apply(int price) { return price; }   // public は必須
    @Override public String label() { return "通常価格"; }
}

class SaleDiscount implements PriceRule {
    private final int percent;
    SaleDiscount(int percent) { this.percent = percent; }
    public int apply(int price) {
        return price - price * percent / 100;
    }
    @Override public String label() { return percent + "%オフ"; }
}

class Checkout {
    private final PriceRule rule;          // 型はインターフェース
    Checkout(PriceRule rule) { this.rule = rule; }
    void pay(int price) {
        System.out.println(rule.label() + ": "
            + PriceRule.yen(price) + " → "
            + PriceRule.yen(rule.apply(price)));
    }
}

// Checkout のコードは一切変えずに、ルールだけ差し替える
new Checkout(new NoDiscount()).pay(2980);
new Checkout(new SaleDiscount(20)).pay(2980);

// Comparable を実装して Arrays.sort で並べ替える
// ここを変えてみよう:compareTo を「高い順」にする(Integer.compare の引数を入れ替える)
class Item implements Comparable<Item> {
    final String name;
    final int price;
    Item(String name, int price) {
        this.name = name;
        this.price = price;
    }
    @Override
    public int compareTo(Item other) {
        // 自分が前なら負、同じなら0、後なら正
        return Integer.compare(price, other.price);
    }
    @Override
    public String toString() { return name + "(" + price + "円)"; }
}

Item[] items = {
    new Item("ボールペン", 150),
    new Item("ノート", 120),
    new Item("ファイル", 300)
};
Arrays.sort(items);   // compareTo の結果だけを頼りに並べる
System.out.println(Arrays.toString(items));

